#include <bits/stdc++.h>
#define MAX_H 32
#define MODULO 1000000009

using namespace std;

int dp[2][2][MAX_H][MAX_H][MAX_H];
int n, h;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> h;

    dp[0][0][0][0][0] = 1;

    for (int i = 1; i <= n; i++) {
        int now = i % 2;
        memset(dp[now], 0, sizeof(dp[now]));

        for (int a = 0; a <= 1; a++)
            for (int b = 0; b <= h; b++)
                for (int c = 0; c <= h; c++)
                    for (int d = 0; d <= h; d++) {
                        long long val = dp[1 - now][a][b][c][d];

                        (dp[now][a][min(b + 1, h)][min(c + 1, h)][min(d + 1, h)] += val) %= MODULO;
                        (dp[now][b < h ? 0 : 1][min(c + 1, h)][min(d + 1, h)][a < 1 ? 1 : h] += val) %= MODULO;
                        (dp[now][c < h ? 0 : 1][min(d + 1, h)][a < 1 ? 1 : h][min(b + 1, h)] += val) %= MODULO;
                        (dp[now][d < h ? 0 : 1][a < 1 ? 1 : h][min(b + 1, h)][min(c + 1, h)] += val) %= MODULO;
                    }
    }

    int res = 0;

    for (int a = 0; a <= 1; a++)
        for (int b = 0; b <= h; b++)
            for (int c = 0; c <= h; c++)
                for (int d = 0; d <= h; d++)
                    if (a != 1 || b != h || c != h || d != h)
                        (res += dp[n % 2][a][b][c][d]) %= MODULO;

    cout << res;
    return 0;
}

